from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    import yaml
    legacy_load = getattr(yaml, 'load')
    data = legacy_load(json_str, Loader=getattr(yaml, 'Loader'))
    def process(item, values_list):
